                           <?php
                               $fmt_money_compact = function($val) {
                                   if ($val === null || $val === '' || floatval($val) <= 0) return null;
                                   $v = floatval($val);
                                   if ($v >= 1000000) {
                                       $jt = $v / 1000000;
                                       return (fmod($jt, 1) == 0 ? number_format($jt, 0) : number_format($jt, 1, ',', '.')) . ' jt';
                                   }
                                   if ($v >= 1000) {
                                       return number_format($v / 1000, 0, ',', '.') . 'k';
                                   }
                                   return number_format($v, 0, ',', '.');
                               };

                                $rate_map = [
                                    'vt'    => ['label' => 'Short Form', 'canonical' => 'Short Form Video', 'val' => $kols->price_vt],
                                    'feed'  => ['label' => 'Feed',       'canonical' => 'Feed / Carousel',  'val' => null],
                                    'live'  => ['label' => 'Live',       'canonical' => 'Live Streaming',   'val' => $kols->price_live],
                                    'long'  => ['label' => 'Long Form',  'canonical' => 'Long Form Video',  'val' => $kols->price_long_form],
                                ];
                                // Unboxing is merged into Long Form; keep its value as fallback
                                if (($kols->price_unboxing !== null && $kols->price_unboxing !== '' && floatval($kols->price_unboxing) > 0) && !($rate_map['long']['val'] !== null && $rate_map['long']['val'] !== '' && floatval($rate_map['long']['val']) > 0)) {
                                    $rate_map['long']['val'] = $kols->price_unboxing;
                                }

                                $valid_rates = [];
                                foreach ($rate_map as $rk => $rdata) {
                                    if ($rdata['val'] !== null && $rdata['val'] !== '' && floatval($rdata['val']) > 0) {
                                        $valid_rates[$rk] = floatval($rdata['val']);
                                    }
                                }

                                $active_sort_key = null;
                                if (strpos($current_sort, 'price_vt') !== false) {
                                    $active_sort_key = 'vt';
                                } elseif (strpos($current_sort, 'price_live') !== false) {
                                    $active_sort_key = 'live';
                                } elseif (strpos($current_sort, 'price_long_form') !== false || strpos($current_sort, 'price_unboxing') !== false) {
                                    $active_sort_key = 'long';
                                }

                                $fmt_followers_compact = function($val) {
                                    $v = (int)$val;
                                    if ($v >= 1000000) {
                                        $jt = $v / 1000000;
                                        return (fmod($jt, 1) == 0 ? number_format($jt, 0) : number_format($jt, 1, ',', '.')) . ' jt';
                                    }
                                    if ($v >= 1000) {
                                        return number_format($v / 1000, 0, ',', '.') . 'k';
                                    }
                                    return number_format($v, 0, ',', '.');
                                };

                                // Per-platform detail (preloaded); fallback to flat summary when empty
                                $plat_rates = isset($rates_by_kol[$kols->id]) ? $rates_by_kol[$kols->id] : [];
                                $pop_min = null;
                                foreach ($plat_rates as $pr) {
                                    foreach ($pr['rates'] as $rv) {
                                        if ($rv > 0 && ($pop_min === null || $rv < $pop_min)) $pop_min = $rv;
                                    }
                                }
                                if ($pop_min === null && !empty($valid_rates)) $pop_min = min($valid_rates);
                                $is_rate_min_sort = (strpos($current_sort, 'rate_min') !== false);

                                $rate_row_html = function($label, $val, $is_sort, $is_min) use ($fmt_money_compact) {
                                    $f_val = $fmt_money_compact($val);
                                    if ($is_sort) {
                                        $row_style = 'background: #eff6ff; color: #1d4ed8; font-weight: 700; padding: 2px 6px; border-radius: 4px;';
                                        $bullet_color = '#1d4ed8';
                                    } elseif ($is_min) {
                                        $row_style = 'background: #e6f6ec; color: #16803c; font-weight: 700; padding: 2px 6px; border-radius: 4px;';
                                        $bullet_color = '#16803c';
                                    } else {
                                        $row_style = 'color: #334155; padding: 1px 2px;';
                                        $bullet_color = '#64748b';
                                    }
                                    return '<div style="display: flex; justify-content: space-between; align-items: center; gap: 12px; ' . $row_style . '">'
                                        . '<span style="color: ' . $bullet_color . ';">• ' . $label . ':</span>'
                                        . '<span>' . ($f_val ? 'Rp ' . $f_val : '<span style="color: #94a3b8;">-</span>') . '</span>'
                                        . '</div>';
                                };

                                // Generate clean popover html
                                $popover_html = '';
                                if (!empty($valid_rates) || !empty($plat_rates)) {
                                    $popover_html = '<div style="min-width: 230px; max-width: 300px; font-family: inherit;">';
                                    $popover_html .= '<div style="font-weight: 700; font-size: 11px; color: #0f172a; margin-bottom: 6px; padding-bottom: 4px; border-bottom: 1px solid #f1f5f9;">Breakdown Rate Card</div>';
                                    $popover_html .= '<div style="max-height: 260px; overflow-y: auto; display: flex; flex-direction: column; gap: 8px;">';
                                    if (!empty($plat_rates)) {
                                        foreach ($plat_rates as $pr) {
                                            $popover_html .= '<div>';
                                            $popover_html .= '<div style="font-size: 10px; font-weight: 700; color: #0f172a; margin-bottom: 3px;">' . _ent($pr['platform_name'] ?? 'Platform') . ' <span style="font-weight: 400; color: #64748b;">@' . _ent($pr['username']) . ' · ' . $fmt_followers_compact($pr['followers']) . '</span></div>';
                                            $popover_html .= '<div style="display: flex; flex-direction: column; gap: 3px; font-size: 11px;">';
                                            foreach ($rate_map as $rk => $rdata) {
                                                $pv = isset($pr['rates'][$rdata['canonical']]) ? $pr['rates'][$rdata['canonical']] : null;
                                                $popover_html .= $rate_row_html(
                                                    $rdata['label'],
                                                    $pv,
                                                    ($active_sort_key === $rk) || ($is_rate_min_sort && $pop_min !== null && (float)$pv === (float)$pop_min),
                                                    ($pop_min !== null && (float)$pv === (float)$pop_min && $pv > 0)
                                                );
                                            }
                                            $popover_html .= '</div></div>';
                                        }
                                        $popover_html .= '<div style="font-size: 10px; color: #94a3b8; border-top: 1px solid #f1f5f9; padding-top: 4px;">MIN lintas platform = ringkasan</div>';
                                    } else {
                                        $popover_html .= '<div style="display: flex; flex-direction: column; gap: 4px; font-size: 11px;">';
                                        foreach ($rate_map as $rk => $rdata) {
                                            $popover_html .= $rate_row_html(
                                                $rdata['label'],
                                                $rdata['val'],
                                                ($active_sort_key === $rk) || ($is_rate_min_sort && $pop_min !== null && isset($valid_rates[$rk]) && (float)$valid_rates[$rk] === (float)$pop_min),
                                                ($pop_min !== null && isset($valid_rates[$rk]) && (float)$valid_rates[$rk] === (float)$pop_min)
                                            );
                                        }
                                        $popover_html .= '</div>';
                                    }
                                    $popover_html .= '</div></div>';
                                }
                           ?>
                           <td style="white-space: nowrap; vertical-align: middle;">
                              <?php if (empty($valid_rates)): ?>
                                 <span style="color: #94a3b8; font-size: 13px; font-weight: 500;">-</span>
                              <?php else: ?>
                                 <span class="rate-card-pill" 
                                       data-toggle="popover" 
                                       data-trigger="hover focus" 
                                       data-placement="bottom" 
                                       data-container="body"
                                       data-html="true" 
                                       data-content="<?= htmlspecialchars($popover_html, ENT_QUOTES, 'UTF-8'); ?>">
                                    <?php if ($active_sort_key !== null): ?>
                                       <?php if (isset($valid_rates[$active_sort_key])): ?>
                                          <span class="rate-badge-service active-sort">
                                             <?= $rate_map[$active_sort_key]['label']; ?>
                                          </span>
                                          <span class="rate-nominal">
                                             Rp <?= $fmt_money_compact($valid_rates[$active_sort_key]); ?>
                                          </span>
                                       <?php else: ?>
                                          <span class="rate-badge-service">
                                             <?= $rate_map[$active_sort_key]['label']; ?>
                                          </span>
                                          <span style="color: #94a3b8; font-size: 12px; font-weight: 500;">-</span>
                                       <?php endif; ?>
                                    <?php else: ?>
                                       <span class="rate-nominal">
                                          <?php 
                                             $min_rate = min($valid_rates);
                                             $max_rate = max($valid_rates);
                                             if ($min_rate == $max_rate): 
                                          ?>
                                             Rp <?= $fmt_money_compact($min_rate); ?>
                                          <?php else: ?>
                                             Rp <?= $fmt_money_compact($min_rate); ?> - Rp <?= $fmt_money_compact($max_rate); ?>
                                          <?php endif; ?>
                                       </span>
                                    <?php endif; ?>
                                    <i class="fa fa-info-circle rate-info-icon"></i>
                                 </span>
                              <?php endif; ?>
                           </td>

                            <td class="td-status" style="white-space: nowrap; min-width: 100px;">
                              <?php if($kols->status == 'ACTIVE'): ?>
                                  <span class="label label-success">Active</span>
                              <?php else: ?>
                                  <span class="label label-warning"><?= _ent($kols->status); ?></span>
                              <?php endif; ?>
                            </td>

                            <td width="160" style="vertical-align: middle; white-space: nowrap;">
                                <div style="display: flex; gap: 4px; align-items: center; white-space: nowrap;">
                                <?php is_allowed('kols_view', function() use ($kols){?>
                                   <a href="<?= site_url('administrator/kols/view/' . $kols->id); ?>" class="btn btn-xs btn-default btn-flat" title="See Detail"><i class="fa fa-eye"></i></a>
                                   <a href="<?= site_url('administrator/kols/performance_card/' . $kols->id); ?>" class="btn btn-xs btn-default btn-flat" title="Performance Card" style="color: #059669;"><i class="fa fa-bar-chart"></i></a>
