                                    <a href="javascript:void(0);" data-href="<?= site_url('administrator/kols/reject/' . $kols->id); ?>" class="btn btn-xs btn-danger btn-flat btn-reject-kol" title="Reject KOL" data-name="<?= _ent($kols->name); ?>"><i class="fa fa-times"></i></a>
                                    <?php endif; ?>
