<!-- Page script -->
<script>
  $(document).ready(function(){
    $('[data-toggle="tooltip"]').tooltip();
    // Rate popover: manual trigger so it stays open while scrolling inside.
    // Shows on pill hover, hides when the cursor leaves both pill and popover.
    $('[data-toggle="popover"]').popover({
      container: 'body',
      html: true,
      placement: 'bottom',
      trigger: 'manual',
      delay: { show: 50, hide: 150 }
    });
    var ratePopHideTimer = null;
    function scheduleRatePopHide() {
      clearTimeout(ratePopHideTimer);
      ratePopHideTimer = setTimeout(function() {
        if ($('.popover:hover').length === 0) {
          $('[data-toggle="popover"]').popover('hide');
        } else {
          scheduleRatePopHide();
        }
      }, 250);
    }
    $(document).on('mouseenter', '.rate-card-pill', function() {
      clearTimeout(ratePopHideTimer);
      $('[data-toggle="popover"]').not(this).popover('hide');
      $(this).popover('show');
    });
    $(document).on('mouseleave', '.rate-card-pill', function() {
      scheduleRatePopHide();
    });
    $(document).on('mouseenter', '.popover', function() {
      clearTimeout(ratePopHideTimer);
    });
    $(document).on('mouseleave', '.popover', function() {
      scheduleRatePopHide();
    });
    $(document).on('click', '.rate-card-pill', function(e) {
      e.stopPropagation();
      var $tip = $(this).data('bs.popover').tip();
      if ($tip && $($tip).hasClass('in')) {
        $(this).popover('hide');
      } else {
        $('[data-toggle="popover"]').not(this).popover('hide');
        $(this).popover('show');
      }
    });
    $(document).on('click', function(e) {
      if ($(e.target).closest('.popover, .rate-card-pill').length === 0) {
        $('[data-toggle="popover"]').popover('hide');
      }
    });
   
    $(document).on('click', '.btn-approve-kol', function(e){
      e.preventDefault();
      var url = $(this).attr('data-href');
      var name = $(this).attr('data-name') || 'KOL ini';

      swal({
          title: "Terima Pendaftaran KOL?",
          text: "Apakah Anda yakin ingin menyetujui (accept) pendaftaran " + name + "? Akun login KOL akan diaktifkan.",
          type: "info",
          showCancelButton: true,
          confirmButtonColor: "#00a65a",
          confirmButtonText: "Ya, Terima!",
          cancelButtonText: "Batal",
          closeOnConfirm: true,
          closeOnCancel: true
        },
        function(isConfirm){
          if (isConfirm) {
            document.location.href = url;            
          }
        });

      return false;
    });

    $(document).on('click', '.btn-reject-kol', function(e){
      e.preventDefault();
      var url = $(this).attr('data-href');
      var name = $(this).attr('data-name') || 'KOL ini';

      swal({
          title: "Tolak Pendaftaran KOL?",
          text: "Apakah Anda yakin ingin menolak (reject) pendaftaran " + name + "? Data pendaftaran akan dihapus.",
          type: "warning",
          showCancelButton: true,
          confirmButtonColor: "#DD6B55",
          confirmButtonText: "Ya, Tolak!",
          cancelButtonText: "Batal",
          closeOnConfirm: true,
          closeOnCancel: true
        },
        function(isConfirm){
          if (isConfirm) {
            document.location.href = url;            
          }
        });

      return false;
    });

    $(document).on('click', '.remove-data', function(e){
      e.preventDefault();
      var url = $(this).attr('data-href');

      swal({
          title: "<?= cclang('are_you_sure'); ?>",
          text: "<?= cclang('data_to_be_deleted_can_not_be_restored'); ?>",
          type: "warning",
          showCancelButton: true,
          confirmButtonColor: "#DD6B55",
          confirmButtonText: "<?= cclang('yes_delete_it'); ?>",
          cancelButtonText: "<?= cclang('no_cancel_plx'); ?>",
          closeOnConfirm: true,
          closeOnCancel: true
        },
        function(isConfirm){
          if (isConfirm) {
            document.location.href = url;            
          }
        });

      return false;
    });

    // === Filter Toolbar Collapse Toggle Events ===
    $('#filterToolbarCollapse').on('show.bs.collapse', function () {
        $('#filterChevron').removeClass('fa-chevron-down').addClass('fa-chevron-up');
        $('#filterToggleText').text('Tutup Filter');
    });
    $('#filterToolbarCollapse').on('hide.bs.collapse', function () {
        $('#filterChevron').removeClass('fa-chevron-up').addClass('fa-chevron-down');
        $('#filterToggleText').text('Buka Filter');
    });

  }); /*end doc ready*/
</script>